#!/usr/bin/env python3
"""Bring ClickHouse master into chdb-core.

The daily workflow (.github/workflows/daily_sync.yml) runs these steps in order.
Each one also works by hand from a clean checkout of main:

  fetch     clone ClickHouse into --work, without blobs; Git fetches those it
            reads
  target    choose the upstream commit to sync to
  apply     apply the upstream diff UPSTREAM_COMMIT..TARGET to the paths chDB
            keeps, and leave any conflict in the work tree, as a merge would
  snapshot  record the sync as applied, before anything builds or edits it
  stage     stage the finished sync (conflicts resolved, build fixed), record what
            the pull request should point out, and write its two commits as patches
  commit    commit the staged sync and write the pull request text

Nothing here pushes; the workflow does that. Per-run files go to .sync/, which
is kept out of Git.
"""

from __future__ import annotations

import argparse
import collections
import datetime as dt
import hashlib
import importlib.util
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import time
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
STATE = ROOT / ".sync"
UPSTREAM_FILE = ROOT / "UPSTREAM_COMMIT"
UPSTREAM_REPO = "ClickHouse/ClickHouse"
UPSTREAM_URL = f"https://github.com/{UPSTREAM_REPO}.git"
UPSTREAM_MASTER = "refs/remotes/origin/master"
PREFLIGHT = ROOT / ".agents/skills/sync-clickhouse-baseline/scripts/sync_preflight.py"
CHDB_HEADER = ROOT / "programs/local/chdb.h"
VERSIONS = ROOT / "cmake/autogenerated_versions.txt"
ZERO = "0" * 40
# GitHub refuses a pull request description longer than 65,536 characters.
PR_BODY_LIMIT = 60000

# MasterCI finishes about four hours after a merge, so the newest commits are
# always still pending. A day without a single green commit means upstream CI
# itself is broken; chDB's own CI then decides whether HEAD is usable.
GREEN_WINDOW_HOURS = 24

# Every marker style git can leave, including the base section of diff3/zdiff3.
CONFLICT_MARKER = re.compile(r"^(<{7}|\|{7}|={7}|>{7})(?: |$)", re.M)


class SyncError(RuntimeError):
    pass


def run(cmd, *, cwd=ROOT, check=True, stdin=None, binary=False, env=None):
    proc = subprocess.run(
        cmd,
        cwd=cwd,
        input=stdin,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=not binary,
        env=env,
    )
    if check and proc.returncode != 0:
        err = proc.stderr if not binary else proc.stderr.decode(errors="replace")
        raise SyncError(f"{' '.join(map(str, cmd[:4]))} ... failed: {err.strip()}")
    return proc


def git(*args, check=True, stdin=None, env=None) -> str:
    return run(["git", *args], check=check, stdin=stdin, env=env).stdout


def upstream_dir(work: Path) -> Path:
    return work / "clickhouse.git"


def ugit(work: Path, *args, check=True, binary=False):
    proc = run(["git", f"--git-dir={upstream_dir(work)}", *args], check=check, binary=binary)
    return proc.stdout


def set_output(**values) -> None:
    path = os.environ.get("GITHUB_OUTPUT")
    if not path:
        return
    with open(path, "a") as fh:
        for key, value in values.items():
            fh.write(f"{key}={value}\n")


def read_upstream_commit() -> str:
    return UPSTREAM_FILE.read_text().split()[0]


def load_module(path: Path, name: str):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    assert spec.loader is not None
    spec.loader.exec_module(module)
    return module


def load_summary() -> dict:
    return json.loads((STATE / "summary.json").read_text())


def save_summary(summary: dict) -> None:
    STATE.mkdir(exist_ok=True)
    (STATE / "summary.json").write_text(json.dumps(summary, indent=2) + "\n")


def keep_state_out_of_git() -> None:
    exclude = Path(git("rev-parse", "--git-path", "info/exclude").strip())
    if not exclude.is_absolute():
        exclude = ROOT / exclude
    exclude.parent.mkdir(parents=True, exist_ok=True)
    lines = exclude.read_text().splitlines() if exclude.exists() else []
    if "/.sync/" not in lines:
        with exclude.open("a") as fh:
            fh.write("/.sync/\n")


def is_ancestor(work: Path, older: str, newer: str) -> bool:
    proc = run(["git", f"--git-dir={upstream_dir(work)}", "merge-base", "--is-ancestor", older, newer], check=False)
    return proc.returncode == 0


# --------------------------------------------------------------------------- fetch


def version_key(tag: str) -> tuple[int, ...]:
    return tuple(int(n) for n in re.findall(r"\d+", tag))


def branch_point_before(work: Path, when: int) -> str | None:
    """The newest `v*.1.1-new` tag (a release branch point) at least a day older than `when`."""
    out = ugit(work, "ls-remote", "--tags", "origin", "refs/tags/v*.1.1-new")
    tags = {line.split("\t")[1].rsplit("/", 1)[-1].replace("^{}", "") for line in out.splitlines() if "\t" in line}
    for tag in sorted(tags, key=version_key, reverse=True):
        ref = f"refs/upstream-tags/{tag}"
        ugit(work, "fetch", "--quiet", "--filter=blob:none", "--no-tags", "--depth=1", "origin",
             f"+refs/tags/{tag}:{ref}")
        if int(ugit(work, "log", "-1", "--format=%ct", ref).strip()) < when - 86400:
            return tag
    return None


def cmd_fetch(args) -> int:
    work = Path(args.work)
    work.mkdir(parents=True, exist_ok=True)
    repo = upstream_dir(work)
    if not (repo / "HEAD").exists():
        git("init", "--bare", "-q", str(repo))
        ugit(work, "remote", "add", "origin", UPSTREAM_URL)
        # A promisor remote: commits and trees now, blobs on demand.
        ugit(work, "config", "remote.origin.promisor", "true")
        ugit(work, "config", "remote.origin.partialclonefilter", "blob:none")
    base = read_upstream_commit()
    fetch = ["fetch", "--quiet", "--filter=blob:none", "--no-tags"]
    ugit(work, *fetch, "--depth=1", "origin", base)
    base_time = int(ugit(work, "log", "-1", "--format=%ct", base).strip())
    # History back to the release branch point before UPSTREAM_COMMIT: enough for
    # `git log` over the range, a fraction of the full history. --shallow-since
    # cannot do this: commits whose dates are older than their parents' cut
    # ClickHouse's master history off at a few days.
    stop = branch_point_before(work, base_time)
    depth = [f"--shallow-exclude={stop}"] if stop else ["--depth=5000"]
    ugit(work, *fetch, *depth, "origin", f"+refs/heads/master:{UPSTREAM_MASTER}", base)
    if args.target:
        # No depth: --depth=1 would cut the history behind a commit the clone has.
        ugit(work, *fetch, "origin", args.target)
    head = ugit(work, "rev-parse", UPSTREAM_MASTER).strip()
    print(f"ClickHouse master is at {head[:12]}; chDB is synced to {base[:12]}")
    return 0


# -------------------------------------------------------------------------- target


def masterci_state(sha: str) -> str:
    proc = run(
        [
            "gh",
            "api",
            f"repos/{UPSTREAM_REPO}/commits/{sha}/status",
            "--jq",
            '[.statuses[] | select(.context == "MasterCI") | .state][0] // "none"',
        ],
        check=False,
    )
    return proc.stdout.strip() if proc.returncode == 0 else "unknown"


def pick_green(work: Path) -> tuple[str, str]:
    now = time.time()
    log = ugit(work, "log", "--first-parent", "--format=%H %ct", "-n", "500", UPSTREAM_MASTER).split("\n")
    entries = [line.split() for line in log if line.strip()]
    head = entries[0][0]
    for sha, committed in entries:
        if now - int(committed) > GREEN_WINDOW_HOURS * 3600:
            break
        if masterci_state(sha) == "success":
            return sha, "newest master commit that passed MasterCI"
    return head, f"no master commit passed MasterCI in {GREEN_WINDOW_HOURS} hours; using master HEAD"


def parse_branch_points(ls_remote: str) -> dict[str, str]:
    """`v*.1.1-new` tag -> the master commit it names, from `git ls-remote` output."""
    points: dict[str, str] = {}
    for line in ls_remote.splitlines():
        sha, _, ref = line.partition("\t")
        tag = ref.rsplit("/", 1)[-1]
        if tag.endswith("^{}"):
            points[tag[: -len("^{}")]] = sha  # an annotated tag, peeled to its commit
        elif tag:
            points.setdefault(tag, sha)
    return points


def next_branch_point(work: Path, base: str, target: str) -> tuple[str, str] | None:
    """The oldest release branch point past base that target reaches, if any.

    Upstream forks release branch X.Y off master at the commit it tags
    v(X.Y+1).1.1-new. The monthly release is cut from the main commit synced to
    exactly that point, so the daily sync stops there on its way past.

    Only the tags fetch fetched count, the ones no older than UPSTREAM_COMMIT; the
    next branch point is among them. Asking about any other one would make Git fetch
    it, and in this partial clone that is the whole history behind it, again for
    every older tag.
    """
    fetched = set(ugit(work, "for-each-ref", "--format=%(refname:lstrip=2)", "refs/upstream-tags/").split())
    out = ugit(work, "ls-remote", "--tags", "origin", "refs/tags/v*.1.1-new*")
    for tag, sha in sorted(parse_branch_points(out).items(), key=lambda point: version_key(point[0])):
        if tag in fetched and is_ancestor(work, sha, target) and not is_ancestor(work, sha, base):
            return tag, sha
    return None


def cmd_target(args) -> int:
    work = Path(args.work)
    base = read_upstream_commit()
    if args.override:
        target = ugit(work, "rev-parse", "--verify", f"{args.override}^{{commit}}").strip()
        reason = "requested by the person who started the run"
    else:
        target, reason = pick_green(work)
        point = next_branch_point(work, base, target)
        if point:
            tag, target = point
            reason = f"the release branch point tagged {tag}, which the monthly release is cut from"

    on_master = is_ancestor(work, base, UPSTREAM_MASTER)
    if target == base or (on_master and is_ancestor(work, target, base)):
        print(f"Nothing to do: {target[:12]} is not newer than UPSTREAM_COMMIT {base[:12]}")
        set_output(target=base, up_to_date="true", reason=reason)
        return 0
    if on_master and not is_ancestor(work, base, target):
        raise SyncError(f"{target[:12]} does not descend from UPSTREAM_COMMIT {base[:12]}")
    print(f"Syncing {base[:12]}..{target[:12]}: {reason}")
    set_output(target=target, up_to_date="false", reason=reason)
    return 0


# --------------------------------------------------------------------------- apply


Change = collections.namedtuple("Change", "old_mode new_mode old_sha new_sha status path")


def parse_raw(raw: str) -> list[Change]:
    """Parse `git diff --raw -z --no-renames` output."""
    parts = raw.split("\0")
    changes = []
    i = 0
    while i + 1 < len(parts):
        meta = parts[i]
        if not meta.startswith(":"):
            i += 1
            continue
        old_mode, new_mode, old_sha, new_sha, status = meta[1:].split()
        changes.append(Change(old_mode, new_mode, old_sha, new_sha, status[0], parts[i + 1]))
        i += 2
    return changes


def classify(changes: list[Change], chdb_paths: set[str], preflight) -> tuple[list[str], list[Change], collections.Counter]:
    """Split upstream changes into files to apply, gitlinks, and skips."""
    files, gitlinks = [], []
    skipped: collections.Counter = collections.Counter()
    for change in changes:
        if "160000" in (change.old_mode, change.new_mode):
            gitlinks.append(change)
            continue
        keep, reason = preflight.scoped_candidate(change.status, [change.path], chdb_paths)
        if keep:
            files.append(change.path)
        else:
            skipped[reason] += 1
    return files, gitlinks, skipped


def apply_gitlinks(changes: list[Change], ours: dict[str, str], preflight) -> list[dict]:
    """Move submodule pointers that chDB shares with upstream; hold the rest."""
    results = []
    for change in changes:
        entry = {"path": change.path, "upstream_old": change.old_sha, "upstream_new": change.new_sha}
        current = ours.get(change.path)
        if change.path.startswith(preflight.DROPPED_TREE_PREFIXES):
            continue
        modes = {change.old_mode, change.new_mode}
        if modes not in ({"160000"}, {"000000", "160000"}):
            entry["action"] = "held: a submodule turned into a file, or back"
        elif change.status == "D":
            if current == change.old_sha:
                git("update-index", "--force-remove", "--", change.path)
                entry["action"] = "removed"
            elif current:
                entry["action"] = "held: chDB pins its own commit"
            else:
                continue
        elif current is None and change.status == "A":
            git("update-index", "--add", "--cacheinfo", f"160000,{change.new_sha},{change.path}")
            entry["action"] = "added"
        elif current is None:
            continue
        elif current != change.old_sha:
            entry["action"] = "held: chDB pins its own commit"
            entry["chdb"] = current
        else:
            git("update-index", "--cacheinfo", f"160000,{change.new_sha},{change.path}")
            entry["action"] = "bumped"
        results.append(entry)
    return results


def follow_upstream_line() -> dict | None:
    """Keep CHDB_VERSION on the ClickHouse line the tree now carries.

    check-abi-version.sh insists on it. Main tracks master, which runs one line
    ahead of the newest release, so the version is a -dev of that line.
    """
    upstream = re.search(r"SET\(VERSION_STRING (\d+)\.(\d+)", VERSIONS.read_text())
    header = CHDB_HEADER.read_text()
    declared = re.search(r'#define CHDB_VERSION "(\d+)\.(\d+)\.[^"]*"', header)
    if not upstream or not declared:
        return None
    if (upstream[1], upstream[2]) == (declared[1], declared[2]):
        return None
    new = f"{upstream[1]}.{upstream[2]}.0-dev"
    CHDB_HEADER.write_text(header.replace(declared.group(0), f'#define CHDB_VERSION "{new}"', 1))
    git("update-index", "--add", "--", str(CHDB_HEADER.relative_to(ROOT)))
    return {"from": declared.group(0).split('"')[1], "to": new}


def merged_prs(work: Path, base: str, target: str) -> list[int]:
    out = ugit(work, "log", "--first-parent", "--format=%s", f"{base}..{target}", check=False) or ""
    return [int(n) for n in re.findall(r"^Merge pull request #(\d+)", out, re.M)]


def copy_blobs(work: Path, shas) -> None:
    """Copy the upstream blobs this repository lacks into it.

    git apply --3way merges a file chDB changed from upstream's version before the
    diff, and a conflict's base (`git show :1:<path>`) is that version too; chDB's
    history does not have it.
    """
    listing = "".join(f"{sha}\n" for sha in sorted(set(shas) - {ZERO}))
    if not listing:
        return
    known = git("cat-file", "--batch-check=%(objectname) %(objecttype)", stdin=listing)
    missing = "".join(line.split()[0] + "\n" for line in known.splitlines() if line.endswith(" missing"))
    if missing:
        pack = run(["git", f"--git-dir={upstream_dir(work)}", "pack-objects", "-q", "--stdout"],
                   stdin=missing.encode(), binary=True).stdout
        run(["git", "index-pack", "--stdin"], stdin=pack, binary=True)


def unmerged_paths() -> list[str]:
    """The paths left in conflict, from the index itself.

    With a conflict left in .gitmodules, the commands below stay with plumbing or
    pass --ignore-submodules: from Git 2.55 on, a command that may look at a
    submodule reads a merged .gitmodules for its settings and dies on the markers.
    """
    entries = (entry.split("\t", 1)[1] for entry in git("ls-files", "-z", "--unmerged").split("\0") if entry)
    return list(dict.fromkeys(entries))


def ensure_clean() -> None:
    dirty = [
        line
        # A reused runner leaves submodules checked out at older pins; the sync only
        # sets the pointers.
        for line in git("status", "--porcelain", "--untracked-files=no", "--ignore-submodules=all").splitlines()
        if line.strip()
    ]
    if dirty:
        raise SyncError("the work tree has local changes; run the sync from a clean checkout of main")


def cmd_apply(args) -> int:
    work = Path(args.work)
    target = args.target
    base = read_upstream_commit()
    ensure_clean()
    STATE.mkdir(exist_ok=True)
    keep_state_out_of_git()
    preflight = load_module(PREFLIGHT, "sync_preflight")

    ours = {}  # path -> (mode, blob) of chDB main
    for entry in git("ls-files", "-s", "-z").split("\0"):
        if entry:
            meta, path = entry.split("\t", 1)
            mode, sha, _stage = meta.split()
            ours[path] = (mode, sha)
    ours_gitlinks = {path: sha for path, (mode, sha) in ours.items() if mode == "160000"}

    changes = parse_raw(ugit(work, "diff", "--raw", "-z", "--no-renames", "--no-abbrev", base, target))
    files, gitlinks, skipped = classify(changes, set(ours), preflight)
    # git apply cannot merge a deletion, and one patch that fails fails them all. A
    # file upstream deleted, or turned into a symlink, after chDB changed it is left
    # out and marked as a modify/delete conflict, as a merge would leave it.
    applied = set(files)
    removed = [c for c in changes if c.path in applied and c.status in ("D", "T") and ours[c.path][1] != c.old_sha]
    files = [p for p in files if p not in {c.path for c in removed}]

    patch = STATE / "upstream.patch"
    with patch.open("wb") as fh:
        for i in range(0, len(files), 400):
            chunk = [f":(literal){p}" for p in files[i : i + 400]]
            fh.write(
                ugit(work, "diff", "--binary", "--full-index", "--no-renames", base, target, "--", *chunk, binary=True)
            )

    copy_blobs(work, [c.old_sha for c in changes if c.path in applied]
               + [c.new_sha for c in removed if c.new_mode != "000000"])
    conflicts: list[str] = []
    if files:
        proc = run(
            ["git", "-c", "merge.conflictStyle=zdiff3", "apply", "--3way", "--index", "--whitespace=nowarn", str(patch)],
            check=False,
        )
        conflicts = unmerged_paths()
        if proc.returncode != 0 and not conflicts:
            raise SyncError(f"git apply failed without leaving conflicts:\n{proc.stderr.strip()}")
    if removed:
        entries = []
        for c in removed:
            mode, sha = ours[c.path]
            entries += [f"0 {ZERO}\t{c.path}", f"{c.old_mode} {c.old_sha} 1\t{c.path}", f"{mode} {sha} 2\t{c.path}"]
            if c.new_mode != "000000":
                entries.append(f"{c.new_mode} {c.new_sha} 3\t{c.path}")
        git("update-index", "-z", "--index-info", stdin="".join(e + "\0" for e in entries))
        conflicts = unmerged_paths()

    submodules = apply_gitlinks(gitlinks, ours_gitlinks, preflight)
    version = follow_upstream_line()
    UPSTREAM_FILE.write_text(target + "\n")
    git("update-index", "--add", "--", UPSTREAM_FILE.name)

    summary = {
        "base": base,
        "target": target,
        "chdb_base": git("rev-parse", "HEAD").strip(),
        "target_reason": os.environ.get("SYNC_TARGET_REASON", ""),
        "upstream_prs": merged_prs(work, base, target),
        "upstream_changes": len(changes),
        "applied_files": files,
        "skipped": dict(skipped.most_common()),
        "conflicts": [{"path": p, **({"note": "deleted upstream"} if p in {c.path for c in removed} else {})}
                      for p in conflicts],
        "submodules": submodules,
        "chdb_version": version,
        "created_at": dt.datetime.now(dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
    }
    save_summary(summary)
    status = "conflicts" if conflicts else "clean"
    set_output(status=status, conflicts=len(conflicts))
    print(
        f"{len(changes)} upstream changes: {len(files)} applied, {sum(skipped.values())} skipped, "
        f"{len(submodules)} submodule changes, {len(conflicts)} conflicts"
    )
    for path in conflicts:
        print(f"  conflict: {path}")
    return 0


# --------------------------------------------------------------------------- stage


def worktree_hash() -> str:
    """A hash of every tracked change against HEAD; build_and_test.sh records the same."""
    diff = run(["git", "diff", "HEAD", "--binary", "--ignore-submodules=dirty"], binary=True).stdout
    return hashlib.sha256(diff).hexdigest()


def gitlinks(env=None) -> dict[str, str]:
    """Submodule path -> the commit the index pins it to."""
    pins = {}
    for line in git("ls-files", "-s", env=env).splitlines():
        meta, path = line.split("\t", 1)
        mode, sha = meta.split()[:2]
        if mode == "160000":
            pins[path] = sha
    return pins


def stage_worktree(env=None) -> str:
    """Stage every change to a tracked file and return the index's tree; env may name another index.

    What `git add -u` does, in plumbing (see unmerged_paths), and without the
    submodules: `git add -u` would also stage whatever each one has checked out, or
    its removal when it is not checked out at all; the pointers stay what apply set.
    """
    pins = gitlinks(env)
    changed = git("ls-files", "-z", "--modified", "--deleted", env=env).split("\0")
    unmerged = [entry.split("\t", 1)[1] for entry in git("ls-files", "-z", "--unmerged", env=env).split("\0") if entry]
    paths = sorted({path for path in changed + unmerged if path and path not in pins})
    if paths:
        git("update-index", "--add", "--remove", "-z", "--stdin", stdin="".join(p + "\0" for p in paths), env=env)
    return git("write-tree", env=env).strip()


def changed_paths(old: str, new: str) -> list[str]:
    return [p for p in git("diff", "--name-only", "-z", "--ignore-submodules=none", old, new).split("\0") if p]


def cmd_snapshot(args) -> int:
    """Record the sync as the script applied it, conflict markers and all, before anything builds or edits it.

    It stages into a copy of the index, so the conflicted files stay unmerged for
    `git diff --name-only --diff-filter=U` to list, as in a monthly upgrade.
    """
    summary = load_summary()
    index = Path(git("rev-parse", "--git-path", "index").strip())
    if not index.is_absolute():
        index = ROOT / index
    with tempfile.TemporaryDirectory() as tmp:
        copy = Path(tmp) / "index"
        shutil.copy(index, copy)
        summary["apply_tree"] = stage_worktree({**os.environ, "GIT_INDEX_FILE": str(copy)})
    save_summary(summary)
    print(f"The applied sync is tree {summary['apply_tree'][:12]}")
    return 0


def cmd_stage(args) -> int:
    """Stage the sync as it stands and note what the reviewer should look at. Never fails a sync.

    Writes what the pull request is made of, as data for the job that holds the
    push token: two patches, the upstream diff as the script applied it
    (.sync/pr-upstream.diff) and everything changed on top of that, by Claude Code
    or a person (.sync/pr-changes.diff), their commit messages
    (.sync/commit-upstream.txt, .sync/commit-changes.txt), and the pull request's
    title and description (.sync/pr_title.txt, .sync/pr_body.md).
    """
    summary = load_summary()
    build_file = STATE / "build.json"
    if build_file.exists():
        build = json.loads(build_file.read_text())
        build["current"] = build.get("tree") == worktree_hash()
        summary["build"] = build
    marker = STATE / "changed_by"
    summary["changed_by"] = marker.read_text().strip() if marker.exists() else ""
    final = stage_worktree()
    applied = summary.get("apply_tree") or final
    conflicts = {c["path"] for c in summary["conflicts"]}
    summary["changed_files"] = changed_paths(applied, final)
    summary["extra_files"] = [p for p in summary["changed_files"] if p not in conflicts]
    summary["markers_left"] = [
        path for path in sorted(conflicts)
        if (ROOT / path).is_file() and CONFLICT_MARKER.search((ROOT / path).read_text(errors="replace"))
    ]
    save_summary(summary)
    base = summary.get("chdb_base", "HEAD")
    patch = ["git", "diff", "--binary", "--ignore-submodules=none"]
    (STATE / "pr-upstream.diff").write_bytes(run([*patch, base, applied], binary=True).stdout)
    (STATE / "pr-changes.diff").write_bytes(run([*patch, applied, final], binary=True).stdout)
    (STATE / "commit-upstream.txt").write_text(commit_message(summary, "upstream"))
    (STATE / "commit-changes.txt").write_text(changes_message(summary))
    (STATE / "pr_title.txt").write_text(commit_title(summary) + "\n")
    (STATE / "pr_body.md").write_text(pr_body(summary))
    set_output(base=base)
    print(f"{len(summary['changed_files'])} files changed on top of the applied sync, "
          f"{len(summary['extra_files'])} of them beyond the conflicts")
    if summary["markers_left"]:
        print("::warning::Conflict markers left in: " + ", ".join(summary["markers_left"]))
    return 0


# -------------------------------------------------------------------------- commit


def commit_title(summary: dict) -> str:
    return f"Sync ClickHouse master up to {summary['target'][:11]}"


def commit_message(summary: dict, part: str = "all") -> str:
    """The sync commit. Part "upstream" is the first of two: the diff as applied, before any fix."""
    lines = [
        commit_title(summary),
        "",
        f"Upstream: {UPSTREAM_REPO} {summary['base'][:11]}..{summary['target'][:11]}, "
        f"{len(summary['upstream_prs'])} merged pull requests.",
    ]
    if summary["conflicts"] and part == "upstream":
        lines.append(f"Conflicts: {len(summary['conflicts'])}, left with their markers; the next commit resolves them.")
    elif summary["conflicts"]:
        lines.append(f"Conflicts resolved: {len(summary['conflicts'])}.")
    actions = collections.Counter(s["action"].split(":")[0] for s in summary["submodules"])
    if actions:
        lines.append("Submodules: " + ", ".join(f"{n} {a}" for a, n in sorted(actions.items())) + ".")
    if summary.get("chdb_version"):
        lines.append(f"CHDB_VERSION follows the new line: {summary['chdb_version']['to']}.")
    return "\n".join(lines) + "\n"


def files(count: int, noun: str) -> str:
    return f"{count} {noun}" + ("" if count == 1 else "s")


def changes_title(summary: dict) -> str:
    conflicts, extra = bool(summary["conflicts"]), bool(summary.get("extra_files"))
    if conflicts and extra:
        title = "Resolve the sync's conflicts and fix the build and tests"
    elif conflicts:
        title = "Resolve the sync's conflicts"
    else:
        title = "Fix the build and tests after the sync"
    return f"{title} ({summary['changed_by']})" if summary.get("changed_by") else title


def changes_message(summary: dict) -> str:
    """The second commit: everything changed on top of the applied upstream diff."""
    by = summary.get("changed_by") or "hand"
    extra = summary.get("extra_files", [])
    lines = [changes_title(summary), "", f"Changes on top of the upstream diff, made by {by}:"]
    if summary["conflicts"]:
        lines.append(f"- {files(len(summary['conflicts']), 'conflicted file')} resolved;")
    if extra:
        lines.append(f"- {files(len(extra), 'other file')} changed to make the build and the tests pass.")
    lines += ["", "The pull request describes each change."]
    return "\n".join(lines) + "\n"


def pr_body(summary: dict) -> str:
    base, target = summary["base"], summary["target"]
    compare = f"https://github.com/{UPSTREAM_REPO}/compare/{base}...{target}"
    out = [
        f"Brings ClickHouse master [{base[:11]}..{target[:11]}]({compare}) into main "
        f"({len(summary['upstream_prs'])} merged upstream pull requests).",
        "",
    ]
    if summary.get("target_reason"):
        out += [f"Target: {summary['target_reason']}.", ""]
    out += [
        f"- Files applied: {len(summary['applied_files'])}",
        f"- Upstream changes skipped (paths chDB does not keep): {sum(summary['skipped'].values())}",
        f"- Conflicts: {len(summary['conflicts'])}",
    ]
    build = summary.get("build")
    if build:
        out += ["", "## Build and tests (Linux x86_64, Python 3.14)", ""]
        if build["result"] == "pass":
            out.append("Built and passed the Python tests.")
        else:
            out.append(f"**Failed at {build.get('step', 'an unknown step')}.**")
        if not build.get("current", True):
            out.append("**The sync changed after this run; the result is for an earlier state.**")
        if build.get("tail"):
            out += ["", "<details><summary>End of the failing output</summary>", "", "```",
                    build["tail"].rstrip(), "```", "", "</details>"]
    if summary["conflicts"]:
        out += ["", "## Conflicts", ""] + [
            f"- `{conflict['path']}`" + (f" ({conflict['note']})" if conflict.get("note") else "")
            for conflict in summary["conflicts"]
        ]
    if summary.get("markers_left"):
        out += ["", "**Conflict markers are still in:** " + ", ".join(f"`{p}`" for p in summary["markers_left"])]
    if summary.get("changed_files"):
        markers = "; the conflicted files still carry their conflict markers" if summary["conflicts"] else ""
        by = summary.get("changed_by") or "hand"
        out += [
            "", "## Commits", "",
            f"1. `{commit_title(summary)}`: the upstream diff as the script applied it{markers}.",
            f"2. `{changes_title(summary)}`: everything changed on top of it, by {by}. Review this one "
            "for what was decided rather than imported.",
        ]
    if summary.get("extra_files"):
        out += ["", "**Files changed beyond the conflicts** (in the second commit; check each): "
                + ", ".join(f"`{p}`" for p in summary["extra_files"])]
    notes = STATE / "resolution.md"
    if notes.exists():
        out += ["", "## What the AI did", "", notes.read_text().strip()]
    if summary["submodules"]:
        out += ["", "## Submodules", "", "| Path | Action | Upstream |", "|---|---|---|"]
        for sub in summary["submodules"]:
            out.append(f"| `{sub['path']}` | {sub['action']} | {sub['upstream_old'][:11]} → {sub['upstream_new'][:11]} |")
    if summary.get("chdb_version"):
        version = summary["chdb_version"]
        out += ["", f"`CHDB_VERSION` moves from `{version['from']}` to `{version['to']}` with the upstream line."]
    checks = STATE / "checks.md"
    if checks.exists():
        out += ["", checks.read_text().strip()]
    out += ["", "Opened by `.github/workflows/daily_sync.yml`; see `.github/nightly/README.md`."]
    body = "\n".join(out) + "\n"
    if len(body) > PR_BODY_LIMIT:
        body = (body[:PR_BODY_LIMIT].rsplit("\n", 1)[0]
                + "\n\n**Cut at GitHub's length limit. The run's `sync-<run id>` artifact has the notes "
                "(`resolution.md`, `checks.md`).**\n")
    return body


def cmd_commit(args) -> int:
    """Commit what stage staged as one commit, for a sync finished by hand."""
    if not git("diff", "--cached", "--name-only", "--ignore-submodules=none").strip():
        raise SyncError("nothing is staged")
    run(["git", "commit", "--quiet", "-F", "-"], stdin=commit_message(load_summary()))
    print(git("log", "-1", "--format=%H %s").strip())
    return 0


# ---------------------------------------------------------------------------- main


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = parser.add_subparsers(dest="command", required=True)

    p = sub.add_parser("fetch")
    p.add_argument("--work", required=True)
    p.add_argument("--target", default="", help="also fetch this upstream commit")
    p.set_defaults(func=cmd_fetch)

    p = sub.add_parser("target")
    p.add_argument("--work", required=True)
    p.add_argument("--override", default="", help="sync to this upstream commit instead")
    p.set_defaults(func=cmd_target)

    p = sub.add_parser("apply")
    p.add_argument("--work", required=True)
    p.add_argument("--target", required=True)
    p.set_defaults(func=cmd_apply)

    p = sub.add_parser("snapshot")
    p.set_defaults(func=cmd_snapshot)

    p = sub.add_parser("stage")
    p.set_defaults(func=cmd_stage)

    p = sub.add_parser("commit")
    p.set_defaults(func=cmd_commit)

    args = parser.parse_args(argv)
    try:
        return args.func(args)
    except SyncError as exc:
        print(f"::error::{exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
